#include <stdio.h>
#include <string.h>
#include <stdbool.h>

int main(int argc, char *argv[]) {
    /* The original binary expects exactly two arguments (pattern and text).
       If the number of arguments is wrong or either string is longer than 64
       characters, it prints a usage message and exits. */
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *pattern = argv[1];
    const char *text    = argv[2];
    size_t p_len = strlen(pattern);
    size_t t_len = strlen(text);

    if (p_len >= 65 || t_len >= 65) {   // limit imposed by the original program
        puts("USAGE");
        return 0;
    }

    /* DP table: dp[i][j] is true if pattern[0..i-1] matches text[0..j-1].
       The original implementation used a flat array with a stride of 0x104
       (256) bytes, but the logical behaviour is the classic wildcard match. */
    bool dp[65][65] = {{false}};
    dp[0][0] = true;

    /* Initialise the first column – a leading sequence of '*' can match an
       empty text. */
    for (size_t i = 1; i <= p_len; ++i) {
        if (pattern[i - 1] == '*')
            dp[i][0] = dp[i - 1][0];
        else
            dp[i][0] = false;
    }
    /* The first row (dp[0][j] for j>0) stays false – a non‑empty text cannot be
       matched by an empty pattern. */

    for (size_t i = 1; i <= p_len; ++i) {
        for (size_t j = 1; j <= t_len; ++j) {
            if (pattern[i - 1] == '*') {
                /* '*' matches zero characters (dp[i-1][j]) or at least one
                   character (dp[i][j-1]). */
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            } else if (pattern[i - 1] == '?' || pattern[i - 1] == text[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = false;
            }
        }
    }

    puts(dp[p_len][t_len] ? "MATCH" : "NO_MATCH");
    return 0;
}
